import{_ as a,o as t,c as o,a3 as i}from"./chunks/framework.CJlOecQn.js";const f=JSON.parse('{"title":"How we source things","description":"The rules every fact in this guide has to pass.","frontmatter":{"title":"How we source things","description":"The rules every fact in this guide has to pass."},"headers":[],"relativePath":"sourcing.md","filePath":"sourcing.md"}'),n={name:"sourcing.md"};function s(r,e,l,c,h,u){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="how-we-source-things" tabindex="-1">How we source things <a class="header-anchor" href="#how-we-source-things" aria-label="Permalink to &quot;How we source things&quot;">​</a></h1><p>This guide has one rule: if we cannot point to an official page for a fact, the fact does not go in.</p><h2 id="what-counts-as-official" tabindex="-1">What counts as official <a class="header-anchor" href="#what-counts-as-official" aria-label="Permalink to &quot;What counts as official&quot;">​</a></h2><ul><li>Government of Qatar websites: Hukoomi and the ministries, councils and authorities on gov.qa, such as the Ministry of Interior, the Ministry of Labour, the Ministry of Public Health and Qatar Central Bank.</li><li>Official law texts on Al Meezan, the legal portal.</li><li>Public bodies and state companies, for their own services: Hamad Medical Corporation, Kahramaa, Mowasalat (Karwa), Qatar Rail, Hamad International Airport, Qatar Post and Visit Qatar.</li><li>The National Human Rights Committee, whose worker booklet supports the labour page.</li><li>Licensed telecom operators, only for facts about their own services.</li></ul><p>The full list is in <a href="https://github.com/Ifazawezk/living-in-qatar/blob/main/scripts/official_domains.txt" target="_blank" rel="noreferrer"><code>scripts/official_domains.txt</code></a>. News articles, forums, blogs, relocation companies and social media posts are never used as sources, even when they turn out to be right. They can be a useful hint about what to look up, nothing more.</p><h2 id="how-a-fact-gets-in" tabindex="-1">How a fact gets in <a class="header-anchor" href="#how-a-fact-gets-in" aria-label="Permalink to &quot;How a fact gets in&quot;">​</a></h2><ol><li>The official page is opened and read.</li><li>The fact is written in plain words, with a footnote to the exact page and the month it was checked.</li><li>The Arabic page cites the same footnotes. A check fails if the two languages cite different sources.</li><li>In the pull request, a script checks that every paragraph, list item and table row has an official source, and a reviewer opens each new link.</li></ol><h2 id="fees-and-numbers" tabindex="-1">Fees and numbers <a class="header-anchor" href="#fees-and-numbers" aria-label="Permalink to &quot;Fees and numbers&quot;">​</a></h2><p>Fees change more often than anything else, so we usually link to the official fee or service page instead of copying an amount. When a number does appear, such as an emergency number or a number of days of leave, it is written on the linked page.</p><h2 id="keeping-it-current" tabindex="-1">Keeping it current <a class="header-anchor" href="#keeping-it-current" aria-label="Permalink to &quot;Keeping it current&quot;">​</a></h2><ul><li>Every footnote ends with &quot;Last checked&quot; and a month.</li><li><code>python scripts/check_links.py</code> visits every source link. It reports links that are dead, links that now redirect somewhere else, and pages whose title changed since the last saved run.</li><li>Some government sites block automated visitors. The checker lists those separately as &quot;blocked&quot; so a person can open them in a browser and confirm them by hand.</li><li><code>python scripts/lint_content.py --stale-after 12</code> warns about sources nobody has checked for a year.</li></ul><h2 id="what-we-leave-out" tabindex="-1">What we leave out <a class="header-anchor" href="#what-we-leave-out" aria-label="Permalink to &quot;What we leave out&quot;">​</a></h2><ul><li>Anything we could not confirm on an official page. Those items go on the <a href="./help-wanted">help wanted</a> list instead.</li><li>Rent and grocery prices, rankings of schools or neighbourhoods, and opinions about employers. There is no official source for these, and they go stale quickly.</li></ul><h2 id="not-legal-advice" tabindex="-1">Not legal advice <a class="header-anchor" href="#not-legal-advice" aria-label="Permalink to &quot;Not legal advice&quot;">​</a></h2><p>This is a community project. It is not run by, or connected to, any government body. It explains where to look and what the official pages say, in plain words. For a decision that matters, read the official page, and if your case is unusual, ask the authority itself.</p>',15)])])}const p=a(n,[["render",s]]);export{f as __pageData,p as default};
